package dev.hrutvik.filesync.blob;
import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import software.amazon.awssdk.auth.credentials.*; import software.amazon.awssdk.regions.Region; import software.amazon.awssdk.services.s3.*; import software.amazon.awssdk.services.s3.presigner.S3Presigner; import java.net.URI;
@Configuration public class BlobStorageConfiguration {
 @Bean S3Client s3Client(@Value("${filesync.blob.region}") String region,@Value("${filesync.blob.endpoint:}") String endpoint,@Value("${filesync.blob.access-key:}") String access,@Value("${filesync.blob.secret-key:}") String secret){var b=S3Client.builder().region(Region.of(region)).forcePathStyle(true);if(!endpoint.isBlank())b.endpointOverride(URI.create(endpoint));if(!access.isBlank())b.credentialsProvider(StaticCredentialsProvider.create(AwsBasicCredentials.create(access,secret)));return b.build();}
 @Bean S3Presigner s3Presigner(@Value("${filesync.blob.region}") String region,@Value("${filesync.blob.endpoint:}") String endpoint,@Value("${filesync.blob.access-key:}") String access,@Value("${filesync.blob.secret-key:}") String secret){var b=S3Presigner.builder().region(Region.of(region)).serviceConfiguration(S3Configuration.builder().pathStyleAccessEnabled(true).build());if(!endpoint.isBlank())b.endpointOverride(URI.create(endpoint));if(!access.isBlank())b.credentialsProvider(StaticCredentialsProvider.create(AwsBasicCredentials.create(access,secret)));return b.build();}
}
